-- =============================================================================================
-- Hand-written below this line: integrity rules, effective-dating rules, share-sum check, row-
-- level security and grants for residents. See docs/architecture/DATA_MODEL.md section 4.
-- Date ranges are calendar dates with INCLUSIVE ends: daterange(from, to, '[]'), NULL = open.
-- =============================================================================================

-- btree_gist lets exclusion constraints combine equality (unit, person) with range overlap.
-- It is a trusted extension: the database owner (veyra_owner) may create it.
CREATE EXTENSION IF NOT EXISTS btree_gist;

-- ---------------------------------------------------------------------------------------------
-- persons
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "persons" ADD CONSTRAINT "persons_full_name_trimmed"
  CHECK ("full_name" = btrim("full_name") AND length("full_name") BETWEEN 1 AND 200);
ALTER TABLE "persons" ADD CONSTRAINT "persons_email_normalised"
  CHECK ("email" IS NULL OR ("email" = lower(btrim("email")) AND position('@' IN "email") > 1 AND length("email") <= 254));
ALTER TABLE "persons" ADD CONSTRAINT "persons_phone_e164"
  CHECK ("phone" IS NULL OR "phone" ~ '^\+[1-9][0-9]{6,14}$');
ALTER TABLE "persons" ADD CONSTRAINT "persons_language_tag"
  CHECK ("preferred_language" IS NULL OR ("preferred_language" ~ '^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$' AND length("preferred_language") <= 35));
ALTER TABLE "persons" ADD CONSTRAINT "persons_archive_consistent"
  CHECK (("status" = 'ARCHIVED') = ("archived_at" IS NOT NULL));
-- One profile per email address in an organisation.
CREATE UNIQUE INDEX "persons_email_unique" ON "persons" ("organisation_id", "email") WHERE "email" IS NOT NULL;

-- ---------------------------------------------------------------------------------------------
-- ownerships
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "ownerships" ADD CONSTRAINT "ownerships_share_fraction"
  CHECK ("share_numerator" > 0 AND "share_denominator" > 0
         AND "share_numerator" <= "share_denominator" AND "share_denominator" <= 1000000);
ALTER TABLE "ownerships" ADD CONSTRAINT "ownerships_period_order"
  CHECK ("effective_to" IS NULL OR "effective_to" >= "effective_from");
ALTER TABLE "ownerships" ADD CONSTRAINT "ownerships_void_reason"
  CHECK (("voided_at" IS NULL) = ("void_reason" IS NULL)
         AND ("void_reason" IS NULL OR length(btrim("void_reason")) BETWEEN 1 AND 500));
-- The same person cannot hold two overlapping ownerships of one unit.
ALTER TABLE "ownerships" ADD CONSTRAINT "ownerships_no_overlap_per_person"
  EXCLUDE USING gist (
    "unit_id" WITH =,
    "person_id" WITH =,
    daterange("effective_from", "effective_to", '[]') WITH &&
  ) WHERE ("voided_at" IS NULL);

-- Exact fraction arithmetic: true when the fractions add up to exactly one.
CREATE FUNCTION app_fractions_sum_to_one(numerators int[], denominators int[]) RETURNS boolean
  LANGUAGE plpgsql IMMUTABLE
  AS $$
DECLARE
  n numeric := 0;
  d numeric := 1;
  g numeric;
BEGIN
  FOR i IN 1 .. coalesce(array_length(numerators, 1), 0) LOOP
    n := n * denominators[i] + numerators[i] * d;
    d := d * denominators[i];
    g := gcd(n, d);
    IF g > 1 THEN n := n / g; d := d / g; END IF;
  END LOOP;
  RETURN n = d;
END
$$;

-- For every date on which the unit has (non-voided) owners, their shares must sum to exactly 1.
-- The sum only changes at a start date or the day after an end date, so those are checked.
CREATE FUNCTION app_assert_ownership_shares(p_unit uuid) RETURNS void
  LANGUAGE plpgsql
  AS $$
DECLARE
  boundary date;
  nums int[];
  dens int[];
BEGIN
  FOR boundary IN
    SELECT "effective_from" FROM "ownerships" WHERE "unit_id" = p_unit AND "voided_at" IS NULL
    UNION
    SELECT "effective_to" + 1 FROM "ownerships"
     WHERE "unit_id" = p_unit AND "voided_at" IS NULL AND "effective_to" IS NOT NULL
  LOOP
    SELECT array_agg("share_numerator"), array_agg("share_denominator") INTO nums, dens
      FROM "ownerships"
     WHERE "unit_id" = p_unit AND "voided_at" IS NULL
       AND "effective_from" <= boundary
       AND ("effective_to" IS NULL OR "effective_to" >= boundary);
    IF nums IS NOT NULL AND NOT app_fractions_sum_to_one(nums, dens) THEN
      RAISE EXCEPTION 'ownership shares of unit % do not sum to 1 on %', p_unit, boundary
        USING ERRCODE = 'check_violation';
    END IF;
  END LOOP;
END
$$;

CREATE FUNCTION app_ownerships_shares_trigger() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE') THEN PERFORM app_assert_ownership_shares(NEW."unit_id"); END IF;
  IF TG_OP IN ('UPDATE', 'DELETE') AND (TG_OP = 'DELETE' OR OLD."unit_id" <> NEW."unit_id") THEN
    PERFORM app_assert_ownership_shares(OLD."unit_id");
  END IF;
  RETURN NULL;
END
$$;

-- Deferred to commit, so a transfer (end one ownership, start another) can happen in one
-- transaction without passing through an invalid intermediate state.
CREATE CONSTRAINT TRIGGER "ownerships_shares_sum_to_one"
  AFTER INSERT OR UPDATE OR DELETE ON "ownerships"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION app_ownerships_shares_trigger();

