-- tenancies and occupants
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "tenancies" ADD CONSTRAINT "tenancies_period_order"
  CHECK ("end_date" IS NULL OR "end_date" >= "start_date");
ALTER TABLE "tenancies" ADD CONSTRAINT "tenancies_void_reason"
  CHECK (("voided_at" IS NULL) = ("void_reason" IS NULL)
         AND ("void_reason" IS NULL OR length(btrim("void_reason")) BETWEEN 1 AND 500));
-- One tenancy per unit at a time.
ALTER TABLE "tenancies" ADD CONSTRAINT "tenancies_no_overlap_per_unit"
  EXCLUDE USING gist (
    "unit_id" WITH =,
    daterange("start_date", "end_date", '[]') WITH &&
  ) WHERE ("voided_at" IS NULL);

-- At most one primary tenant per tenancy (the API requires exactly one when creating).
CREATE UNIQUE INDEX "tenancy_occupants_one_primary" ON "tenancy_occupants" ("tenancy_id") WHERE "is_primary";

