  CHECK ("name" = btrim("name") AND length("name") BETWEEN 1 AND 200);
ALTER TABLE "emergency_contacts" ADD CONSTRAINT "emergency_contacts_phone_e164"
  CHECK ("phone" ~ '^\+[1-9][0-9]{6,14}$');

ALTER TABLE "vehicles" ADD CONSTRAINT "vehicles_plate_normalised"
