  ON "vehicles" ("property_id", "plate") WHERE "status" = 'ACTIVE';

-- ---------------------------------------------------------------------------------------------
-- Row-level security: tenant context only (MULTI_TENANCY section 3.3).
-- ---------------------------------------------------------------------------------------------
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['persons', 'ownerships', 'tenancies', 'tenancy_occupants',
                           'household_members', 'emergency_contacts', 'vehicles'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
END
$$;
-- Emergency contacts are not history and can be removed.
CREATE POLICY "emergency_contacts_delete" ON "emergency_contacts" FOR DELETE
  USING ("organisation_id" = app_current_organisation_id());

-- ---------------------------------------------------------------------------------------------
-- Least privilege: no DELETE except emergency contacts; mistakes are voided, not removed.
-- ---------------------------------------------------------------------------------------------
REVOKE ALL ON "persons", "ownerships", "tenancies", "tenancy_occupants", "household_members",
  "emergency_contacts", "vehicles" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "persons", "ownerships", "tenancies", "tenancy_occupants",
  "household_members", "emergency_contacts", "vehicles" TO veyra_app;
GRANT DELETE ON "emergency_contacts" TO veyra_app;
